function Nav({ currentPage, setPage }) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  const go = (page) => { setPage(page); setMobileOpen(false); window.scrollTo(0,0); };
  const links = [
    { label:"Home", page:"home" }, { label:"About", page:"about" },
    { label:"Offers", page:"offers" }, { label:"Book a Session", page:"book" },
    { label:"Contact", page:"contact" }
  ];
  return (
    <>
      <nav className={scrolled ? "scrolled" : ""}>
        <Logo onClick={() => go("home")} />
        <ul className="nav-links">
          {links.map(l => (
            <li key={l.page}>
              <a className={currentPage === l.page ? "active" : ""} onClick={() => go(l.page)}>{l.label}</a>
            </li>
          ))}
        </ul>
        <button className="hamburger" onClick={() => setMobileOpen(true)} aria-label="Menu">
          <span /><span /><span />
        </button>
      </nav>
      <div className={`mobile-nav ${mobileOpen ? "open" : ""}`}>
        <button className="modal-close" style={{position:"absolute",top:"1.5rem",right:"1.5rem",fontSize:"1.5rem"}} onClick={() => setMobileOpen(false)}>✕</button>
        {links.map(l => <a key={l.page} onClick={() => go(l.page)}>{l.label}</a>)}
      </div>
    </>
  );
}

function Modal({ offer, onClose, setPage }) {
  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  }, []);
  const handleCta = () => {
    onClose();
    setPage(offer.cta === "book" ? "book" : "contact");
    window.scrollTo(0,0);
  };
  return (
    <div className="modal-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-header">
          <button className="modal-close" onClick={onClose}>✕</button>
          <div className="modal-eyebrow">{offer.label}</div>
          <div className="modal-title">{offer.title}</div>
          <div className="modal-subtitle">{offer.subtitle}</div>
        </div>
        <div className="modal-body">
          {offer.sections.map((sec, i) => (
            <div className="modal-section" key={i}>
              <div className="modal-section-title">{sec.title}</div>
              {sec.content && (
                <div className="modal-text">
                  {sec.content.split('\n\n').map((p, j) => <p key={j}>{p}</p>)}
                </div>
              )}
              {sec.list && (
                <ul className="modal-list">
                  {sec.list.map((item, j) => <li key={j}>{item}</li>)}
                </ul>
              )}
            </div>
          ))}
          <div className="pricing-block">
            <div className="modal-section-title" style={{borderBottom:"none",paddingBottom:0,marginBottom:"0.5rem"}}>Investment</div>
            {offer.pricing.map((tier, i) => (
              <div className="pricing-tier" key={i}>
                <div className="pricing-name">{tier.name}<small>{tier.detail}</small></div>
                <div className="pricing-amount">{tier.amount}</div>
              </div>
            ))}
            {offer.pricingNote && <p style={{fontSize:"0.72rem",color:"#F4E8D4",marginTop:"1.25rem",lineHeight:1.7}}>{offer.pricingNote}</p>}
          </div>
          <div className="modal-cta-row">
            <button className="btn-primary" onClick={handleCta}>{offer.ctaLabel}</button>
            <button className="btn-secondary" onClick={onClose}>Close</button>
          </div>
        </div>
      </div>
    </div>
  );
}

