export default function App() {
  const [currentPage, setCurrentPage] = useState("home");
  const [activeOffer, setActiveOffer] = useState(null);
  const setPage = (page) => setCurrentPage(page);
  const openOffer = (offer) => setActiveOffer(offer);
  const closeOffer = () => setActiveOffer(null);
  return (
    <>
      <FontLoader />
      <Nav currentPage={currentPage} setPage={setPage} />
      {currentPage === "home"    && <HomePage    setPage={setPage} openOffer={openOffer} />}
      {currentPage === "about"   && <AboutPage   />}
      {currentPage === "offers"  && <OffersPage  openOffer={openOffer} />}
      {currentPage === "book"    && <BookPage    />}
      {currentPage === "contact" && <ContactPage />}
      <Footer setPage={setPage} />
      {activeOffer && <Modal offer={activeOffer} onClose={closeOffer} setPage={setPage} />}
    </>
  );
}
